// FG's random encounters and Generate:
//  - a campaign encounter's counts (1d4+1, $PC the party's size, 2, 0) rolled into a new encounter of numbers; a
//    creature that comes to 0 left out; the encounter it came from kept as it was; the new one runs on the tracker
//  - a book's random encounter (FG's battlerandom: "expr" counts, its creatures linked within the book) listed with
//    the encounters as random, generated by its path, its creatures the book's, run on the tracker
//  - $PC taken as a count; the GM's alone
import "./loopback.mjs";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createRequire } from "node:module";
import { zipSync, strToU8 } from "fflate";

const require = createRequire(import.meta.url);
const { createTableServer } = require("../electron/tableServer.cjs");
const { createBookShelf } = require("../electron/books.cjs");
const { callTool } = require("../electron/agent/tools.cjs");
const content = require("../electron/content.cjs");
const library = require("../electron/library.cjs");
const { partyRecord, PARTY_ID } = require("../electron/party.cjs");

function assert(condition, message) {
  if (!condition) throw new Error(message);
}
const done = [];
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "kraken-generate-"));
const db = `<root><npc><id-00001><name type="string">Quarry Wolf</name><ac type="number">13</ac><hp type="number">11</hp><xp type="number">50</xp></id-00001></npc><battlerandom><id-00001><name type="string">Random 2-3 Wolves</name><npclist><id-00001><name type="string">Quarry Wolf</name><expr type="string">1d2+1</expr><link type="windowreference"><class>npc</class><recordname>npc.id-00001</recordname></link></id-00001></npclist></id-00001></battlerandom></root>`;
fs.writeFileSync(path.join(dir, "Wolf Quarry.mod"), zipSync({ "definition.xml": strToU8("<root><name>Wolf Quarry</name><category>Adventures</category><ruleset>5E</ruleset></root>"), "db.xml": strToU8(db) }));
const server = createTableServer({ books: createBookShelf({ folder: dir }), ruleset: "D&D 5E" });
await server.listen({ port: 0, password: "" });
const tool = async (name, args) => {
  const result = await callTool(name, args, { table: () => server });
  if (result.isError) throw new Error(`${name}: ${result.content[0].text}`);
  return JSON.parse(result.content[0].text);
};
const a = server.agent;
try {
  const heroes = ["Ann", "Bob", "Cy"].map((owner) => a.records.create({ type: "character", name: `${owner}'s hero`, owner, data: {} }, a.seat).id);
  partyRecord(a);
  a.records.update(PARTY_ID, { data: { members: heroes } }, a.seat);
  const npc = (name) => a.records.create({ type: "npc", name, data: { ac: 12, hp: 7, xp: 50 } }, a.seat);
  const [goblin, wolf, rat, bugbear] = ["Goblin", "Wolf", "Rat", "Bugbear"].map(npc);
  const battle = await tool("kraken_encounter", { action: "create", name: "Road Ambush" });
  for (const [creature, count] of [[goblin, "1d4+1"], [wolf, "$PC"], [rat, "0"], [bugbear, "2"]]) await tool("kraken_encounter", { action: "add-npc", id: battle.id, npc: creature.id, count });

  // 1. A campaign encounter generated.
  a.dice.force([3]);
  const made = await tool("kraken_encounter", { action: "generate", id: battle.id });
  const rows = Object.values(a.records.get(made.id).data.npclist);
  assert(made.id !== battle.id && made.name === "Road Ambush" && rows.map((row) => `${row.count} ${row.name}`).join(", ") === "4 Goblin, 3 Wolf, 2 Bugbear", `generated: ${JSON.stringify(made.rolled)} ${JSON.stringify(rows)}`);
  assert(Object.values(a.records.get(battle.id).data.npclist).map((row) => row.count).join() === "1d4+1,$PC,0,2", "the random one kept as it was");
  assert(a.chatLog(3).some((line) => /\[ENCOUNTER\] Generated Road Ambush: 4 Goblin, 3 Wolf, 2 Bugbear/.test(line.text ?? "")), "said to the GM");
  const ran = await tool("kraken_encounter", { action: "run", id: made.id, place: false });
  assert(ran.added.length === 9, `it runs: ${ran.added.length}`);
  done.push("a campaign encounter: 1d4+1, $PC and 2 rolled, a 0 left out, the random one kept, the new one run");

  // 2. A book's random encounter.
  await tool("kraken_books", { action: "activate", book: "Wolf Quarry" });
  const listed = library.list("Wolf Quarry", "battle");
  assert(listed.length === 1 && listed[0].random && listed[0].npcs === "1d2+1 Quarry Wolf", `listed with the encounters as random: ${JSON.stringify(listed)}`);
  a.dice.force([2]);
  const fromBook = await tool("kraken_encounter", { action: "generate", path: listed[0].path });
  const row = Object.values(a.records.get(fromBook.id).data.npclist)[0];
  assert(fromBook.name === "Random 2-3 Wolves" && row.count === "3" && row.link.recordname === "npc.id-00001@Wolf Quarry" && !row.expr, `from the book: ${JSON.stringify(row)}`);
  await tool("kraken_combat", { action: "clear" }).catch(() => undefined);
  const wolves = await tool("kraken_encounter", { action: "run", id: fromBook.id, place: false });
  assert(wolves.added.length === 3 && wolves.added.every((name) => /Quarry Wolf/.test(name)), `the book's wolves on the tracker: ${JSON.stringify(wolves)}`);
  done.push("a book's random encounter listed, generated by its path, its wolves the book's, run");

  // 3. Counts and who may.
  let bad = "";
  try {
    await tool("kraken_encounter", { action: "add-npc", id: battle.id, npc: goblin.id, count: "many" });
  } catch (error) {
    bad = String(error);
  }
  assert(/A count is a number or dice/.test(bad), "a count that is not one refused");
  let refused = "";
  try {
    await content.message(a, { type: "encounter", action: "generate", id: battle.id }, { seat: { role: "player", name: "Ann" } });
  } catch (error) {
    refused = String(error);
  }
  assert(/GM's/.test(refused), "a player may not generate");
  done.push("counts checked; the GM's alone");
} finally {
  await server.stop?.();
  fs.rmSync(dir, { recursive: true, force: true });
}
console.log(`ok encounter generate: ${done.join("; ")}`);
process.exit(0);
